def isEulerCircuit(V, adj):
    def dfs(v, visited):
        visited[v] = True
        for neighbor in adj[v]:
            if not visited[neighbor]:
                dfs(neighbor, visited)

    visited = [False] * V
    start_vertex = -1

    # Find a vertex with non-zero degree
    for i in range(V):
        if len(adj[i]) > 0:
            start_vertex = i
            break

    if start_vertex == -1:
        return 2  # No edges, trivially Eulerian circuit

    # Check if all non-zero degree vertices are connected
    dfs(start_vertex, visited)
    for i in range(V):
        if len(adj[i]) > 1 and not visited[i]:
            return 0

    # Count vertices with odd degree
    odd_degree_count = sum(1 for i in range(V) if len(adj[i]) % 2 != 0)

    if odd_degree_count == 0:
        return 2  # Eulerian circuit
    elif odd_degree_count == 2:
        return 1  # Eulerian path
    else:
        return 0  # No Eulerian path or circuit

